# -*- coding: utf-8 -*-
"""
store.py
========
Zentraler Zugriff auf die einzige Speicherdatei ``mem.json``.

``mem.json`` besteht aus benannten Abschnitten (Sections). Seit dem
Profil-Update liegt fast alles UNTER einem Spielerprofil::

    {
      "_generated": "generated by PyGameZ at ... (YYYY-MM-DD HH:MM:SS)",
      "mem":      { "lang": "de" },          # gerätweit (Sprache der Oberfläche)
      "profiles": { "active": "p1",          # aktives Profil
                    "order":  ["p1", "p2"],  # Anzeige-Reihenfolge
                    "list":   { "p1": {"name": "Lama", "icon": "llama",
                                       "color": 0, "created": "...",
                                       "seen": "..."} } },
      "players":  { "p1": { "highscores": {...}, "achievements": {...},
                            "casino": {...}, "chess": {...}, ... } }
    }

Jedes Modul liest/schreibt nur seinen eigenen Abschnitt über
``load_section``/``save_section`` - dabei bleibt der Rest der Datei erhalten
(gelesen -> geändert -> komplett zurückgeschrieben). Die Abschnitte landen
automatisch beim aktiven Profil; nur die in ``SHARED_SECTIONS`` genannten
(die Sprache) gelten für das ganze Gerät. Für die Spiele ändert sich dadurch
nichts: Sie rufen weiterhin ``store.load_section("tetris")`` auf.

Alte Formate werden beim ersten Laden automatisch übernommen:

- getrennte ``highscores.json`` bzw. flaches ``mem.json`` mit ``lang`` oben,
- Dateien OHNE Profile: alle vorhandenen Abschnitte wandern in ein
  Standardprofil (Name = Benutzername des Betriebssystems).

Achtung: Nach dieser Migration findet eine ÄLTERE PyGameZ-Version ihre Daten
nicht mehr (sie sucht die Abschnitte oben in der Datei). Die Sicherung
``mem.json.bak`` bleibt liegen.
"""

import json
import os
import sys
import time

# In einer PyInstaller-.exe (sys.frozen) zeigt __file__ in den temporären
# Entpack-Ordner, der beim Beenden verschwindet - dann neben der .exe speichern.
if getattr(sys, "frozen", False):
    _DIR = os.path.dirname(sys.executable)
else:
    _DIR = os.path.dirname(os.path.abspath(__file__))
_PATH = os.path.join(_DIR, "mem.json")
# Früherer, separater Speicherort der Highscores (nur noch für die Migration).
_LEGACY_HS_PATH = os.path.join(_DIR, "highscores.json")

# Abschnitte, die für das ganze Gerät gelten (nicht je Profil).
SHARED_SECTIONS = ("mem",)

# Schlüssel der beiden Verwaltungs-Abschnitte.
_PROFILES = "profiles"
_PLAYERS = "players"

# Mehr Profile passen weder auf den Bildschirm noch in einen Haushalt.
MAX_PROFILES = 8

# Standard-Profil-id (erstes Profil, bekommt bei der Migration alle Altdaten).
FIRST_ID = "p1"

# Rückrufe, die nach einem Profilwechsel die Zwischenspeicher leeren
# (stats, achievements, lamabank, ngb ... melden sich per on_switch an).
_switch_callbacks = []


def data_dir():
    """Ordner, in dem die Spieldaten liegen (neben der .exe bzw. dem Quelltext)."""
    return _DIR


def path_for(filename):
    """Vollständiger Pfad einer Datei im Datenordner (z.B. stats.pgzlamastats)."""
    return os.path.join(_DIR, filename)


def _read_json(path):
    """Liest eine JSON-Datei als dict (None bei Fehler/fehlender Datei)."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
            return data if isinstance(data, dict) else None
    except (OSError, json.JSONDecodeError, ValueError):
        return None


def _read_raw():
    """Liest mem.json roh (immer ein dict, leer bei Fehler/fehlender Datei).

    Ist mem.json beschädigt oder fehlt sie nach einem abgebrochenen Speichern,
    wird die Sicherung mem.json.bak (Stand vor dem letzten Speichern) gelesen -
    sonst würde das nächste Speichern alle Highscores, Erfolge und Chips
    mit einer leeren Datei überschreiben.
    """
    data = _read_json(_PATH)
    if data is None:
        data = _read_json(_PATH + ".bak")
    return data if data is not None else {}


def write_json_atomic(path, obj, indent=2):
    """Schreibt 'obj' als JSON, ohne dass ein Absturz die Datei zerstören kann.

    Erst in eine Temp-Datei daneben, dann per os.replace an die richtige
    Stelle (atomar). Die vorherige Fassung bleibt als '<path>.bak' liegen.
    Gibt True bei Erfolg zurück; Fehler (z.B. keine Schreibrechte) werden
    geschluckt, damit das Spiel ohne Persistenz weiterläuft.
    """
    tmp = path + ".tmp"
    try:
        text = json.dumps(obj, indent=indent, ensure_ascii=False)
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(text)
            f.flush()
            try:
                os.fsync(f.fileno())
            except OSError:
                pass
        if os.path.exists(path):
            try:
                os.replace(path, path + ".bak")
            except OSError:
                pass
        os.replace(tmp, path)
        return True
    except (OSError, TypeError, ValueError):
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except OSError:
            pass
        return False


def _read_legacy_highscores():
    """Liest eine evtl. noch vorhandene alte highscores.json (leer bei Fehler)."""
    try:
        with open(_LEGACY_HS_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
            return data if isinstance(data, dict) else {}
    except (OSError, json.JSONDecodeError, ValueError):
        return {}


def _os_user_name():
    """Benutzername des Betriebssystems als Vorschlag für das erste Profil.

    Leerer String, wenn er sich nicht ermitteln lässt oder unbrauchbar ist -
    die Oberfläche zeigt dann "Spieler 1" (t("profile.default")).
    """
    try:
        import getpass
        name = (getpass.getuser() or "").strip()
    except Exception:
        return ""
    # Nur druckbare Zeichen, höchstens so lang wie ein Profilname sein darf.
    name = "".join(c for c in name if c.isprintable()).strip()
    return name[:14]


def _blank_meta(name=""):
    stamp = time.strftime("%Y-%m-%d %H:%M")
    return {"name": name, "icon": "llama", "color": 0,
            "created": stamp, "seen": stamp}


def _clean_meta(raw, fallback_name=""):
    """Bringt einen Profil-Eintrag auf die erwartete Form (fehlertolerant)."""
    meta = _blank_meta(fallback_name)
    if isinstance(raw, dict):
        name = raw.get("name")
        if isinstance(name, str):
            meta["name"] = name.strip()[:14]
        icon = raw.get("icon")
        if isinstance(icon, str) and icon:
            meta["icon"] = icon[:24]
        color = raw.get("color")
        if isinstance(color, int) and not isinstance(color, bool):
            meta["color"] = max(0, min(11, color))
        for key in ("created", "seen"):
            value = raw.get(key)
            if isinstance(value, str) and value:
                meta[key] = value[:19]
    return meta


def _normalize(data):
    """Bringt alte Formate auf die aktuelle Struktur.

    Gibt (normalisiertes_dict, wurde_geändert) zurück.
    """
    changed = False

    # Abschnitt "mem": früher lagen Schlüssel wie "lang" direkt oben.
    if not isinstance(data.get("mem"), dict):
        mem = {}
        for key in ("lang",):
            if key in data:
                mem[key] = data.pop(key)
        data["mem"] = mem
        changed = True

    # --- Profile ---------------------------------------------------------
    # Fehlt der Profil-Abschnitt, stammt die Datei aus einer Version vor dem
    # Profil-Update: alle vorhandenen Spiel-Abschnitte wandern in Profil 1.
    profiles = data.get(_PROFILES)
    players = data.get(_PLAYERS)
    if not isinstance(profiles, dict) or not isinstance(profiles.get("list"), dict) \
            or not profiles["list"]:
        moved = {}
        for key in list(data.keys()):
            if key == "_generated" or key in SHARED_SECTIONS \
                    or key in (_PROFILES, _PLAYERS):
                continue
            value = data.pop(key)
            if isinstance(value, dict):
                moved[key] = value
        if not isinstance(players, dict):
            players = {}
        old = players.get(FIRST_ID)
        if isinstance(old, dict):
            old.update(moved)
            moved = old
        players[FIRST_ID] = moved
        profiles = {"active": FIRST_ID, "order": [FIRST_ID],
                    "list": {FIRST_ID: _blank_meta(_os_user_name())}}
        data[_PROFILES] = profiles
        data[_PLAYERS] = players
        changed = True

    # Verwaltungsdaten säubern (beschädigte Datei darf nicht alles kippen).
    if not isinstance(data.get(_PLAYERS), dict):
        data[_PLAYERS] = {}
        changed = True
    plist = {}
    for pid, meta in profiles["list"].items():
        pid = str(pid)
        if pid:
            plist[pid] = _clean_meta(meta)
    if not plist:
        plist = {FIRST_ID: _blank_meta(_os_user_name())}
        changed = True
    order = [str(p) for p in profiles.get("order", []) if str(p) in plist]
    for pid in plist:
        if pid not in order:
            order.append(pid)
    active = str(profiles.get("active") or "")
    if active not in plist:
        active = order[0]
    new_profiles = {"active": active, "order": order, "list": plist}
    if new_profiles != profiles:
        data[_PROFILES] = new_profiles
        changed = True
    for pid in plist:
        if not isinstance(data[_PLAYERS].get(pid), dict):
            data[_PLAYERS][pid] = {}
            changed = True

    # Abschnitt "highscores" des aktiven Profils: ggf. aus alter
    # highscores.json übernehmen (nur beim allerersten Start relevant).
    slot = data[_PLAYERS][active]
    if not isinstance(slot.get("highscores"), dict):
        slot["highscores"] = _read_legacy_highscores()
        changed = True

    return data, changed


def load():
    """Liest mem.json als vollständiges dict (mit Abschnitten) und migriert bei Bedarf."""
    data, changed = _normalize(_read_raw())
    if changed:
        save(data)
    return data


def save(data):
    """Schreibt das vollständige dict nach mem.json (Fehler werden ignoriert).

    "_generated" (Anlege-Datum der Datei) steht immer als erster Eintrag;
    ein bereits vorhandener Stempel bleibt erhalten.
    """
    stamp = data.get("_generated")
    if not (isinstance(stamp, str) and stamp):
        stamp = ("generated by PyGameZ at " + time.strftime("%Y-%m-%d %H:%M:%S")
                 + " (YYYY-MM-DD HH:MM:SS)")
    out = {"_generated": stamp}
    out.update((k, v) for k, v in data.items() if k != "_generated")
    # Schlägt das Speichern fehl (z.B. keine Schreibrechte), läuft das
    # Spiel trotzdem weiter - nur ohne Persistenz.
    write_json_atomic(_PATH, out)


# ---------------------------------------------------------------------------
#  Abschnitte (je Profil, außer den gerätweiten aus SHARED_SECTIONS)
# ---------------------------------------------------------------------------

def load_section(name, profile=None):
    """Liefert den Abschnitt 'name' als dict (leer, wenn nicht vorhanden).

    Ohne 'profile' gilt das aktive Profil; gerätweite Abschnitte
    (SHARED_SECTIONS) liegen unabhängig davon oben in der Datei.
    """
    data = load()
    if name in SHARED_SECTIONS:
        section = data.get(name)
    else:
        pid = profile or data[_PROFILES]["active"]
        section = data.get(_PLAYERS, {}).get(pid, {}).get(name)
    return section if isinstance(section, dict) else {}


def save_section(name, section, profile=None):
    """Ersetzt den Abschnitt 'name' und schreibt die ganze Datei zurück."""
    data = load()
    if name in SHARED_SECTIONS:
        data[name] = section
    else:
        pid = profile or data[_PROFILES]["active"]
        slot = data.setdefault(_PLAYERS, {}).setdefault(pid, {})
        slot[name] = section
    save(data)


# ---------------------------------------------------------------------------
#  Profile
# ---------------------------------------------------------------------------

def active_id():
    """id des aktiven Profils."""
    return load()[_PROFILES]["active"]


def profile_ids():
    """Alle Profil-ids in Anzeige-Reihenfolge."""
    return list(load()[_PROFILES]["order"])


def profile_meta(pid=None):
    """Kopfdaten eines Profils ({name, icon, color, created, seen})."""
    data = load()
    pid = pid or data[_PROFILES]["active"]
    meta = data[_PROFILES]["list"].get(pid)
    return dict(meta) if meta else _blank_meta()


def all_profiles():
    """[(id, meta), ...] in Anzeige-Reihenfolge."""
    data = load()
    plist = data[_PROFILES]["list"]
    return [(pid, dict(plist[pid])) for pid in data[_PROFILES]["order"]
            if pid in plist]


def set_meta(pid, **fields):
    """Ändert einzelne Kopfdaten eines Profils (name/icon/color/seen)."""
    data = load()
    meta = data[_PROFILES]["list"].get(pid)
    if meta is None:
        return False
    for key, value in fields.items():
        if key in ("name", "icon", "color", "seen", "created"):
            meta[key] = value
    data[_PROFILES]["list"][pid] = _clean_meta(meta)
    save(data)
    return True


def touch(pid=None):
    """Merkt sich, wann ein Profil zuletzt gespielt hat."""
    data = load()
    pid = pid or data[_PROFILES]["active"]
    if pid in data[_PROFILES]["list"]:
        data[_PROFILES]["list"][pid]["seen"] = time.strftime("%Y-%m-%d %H:%M")
        save(data)


def _next_id(plist):
    """Erste freie Profil-id ("p2", "p3", ...)."""
    i = 1
    while ("p%d" % i) in plist:
        i += 1
    return "p%d" % i


def create_profile(name="", icon="llama", color=0):
    """Legt ein neues Profil an und gibt seine id zurück (None, wenn voll)."""
    data = load()
    plist = data[_PROFILES]["list"]
    if len(plist) >= MAX_PROFILES:
        return None
    pid = _next_id(plist)
    meta = _blank_meta()
    meta.update(name=name, icon=icon, color=color)
    plist[pid] = _clean_meta(meta)
    data[_PROFILES]["order"].append(pid)
    data.setdefault(_PLAYERS, {})[pid] = {}
    save(data)
    return pid


def delete_profile(pid):
    """Löscht ein Profil samt seinen Daten (das letzte bleibt bestehen)."""
    data = load()
    profiles = data[_PROFILES]
    if pid not in profiles["list"] or len(profiles["list"]) <= 1:
        return False
    profiles["list"].pop(pid, None)
    profiles["order"] = [p for p in profiles["order"] if p != pid]
    data.get(_PLAYERS, {}).pop(pid, None)
    if profiles["active"] == pid:
        profiles["active"] = profiles["order"][0]
    save(data)
    _fire_switch()
    return True


def set_active(pid):
    """Wechselt das aktive Profil (leert alle Zwischenspeicher)."""
    data = load()
    if pid not in data[_PROFILES]["list"] or data[_PROFILES]["active"] == pid:
        return False
    data[_PROFILES]["active"] = pid
    data[_PROFILES]["list"][pid]["seen"] = time.strftime("%Y-%m-%d %H:%M")
    save(data)
    _fire_switch()
    return True


def on_switch(callback):
    """Meldet einen Rückruf an, der nach jedem Profilwechsel läuft.

    Module mit In-Memory-Zwischenspeicher (stats, achievements, lamabank,
    ngb ...) leeren darin ihre Kopien, damit sie die Daten des neuen Profils
    frisch lesen.
    """
    if callback not in _switch_callbacks:
        _switch_callbacks.append(callback)


def _fire_switch():
    for callback in list(_switch_callbacks):
        try:
            callback()
        except Exception:
            # Ein Profilwechsel darf nie am Aufräumen eines Moduls scheitern.
            pass
